type Ok<T> = { ok: true; value: T };
type Err = { ok: false; error: Error };
function parseJSONSafe<T = unknown>(text: string): Ok<T> | Err {
  try { return { ok: true, value: JSON.parse(text) as T }; }
  catch (e) { return { ok: false, error: e instanceof Error ? e : new Error(String(e)) }; }
}
